const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const headers = (item.json && item.json.headers) || {};
const ts = headers['x-lit-timestamp'];
const eventId = headers['x-lit-event-id'];
const signature = headers['x-lit-signature'];
if (!ts || !eventId || !signature) { throw new Error('Missing signing headers'); }
const body = (item.json && item.json.body) !== undefined ? item.json.body : {};
const rawBody = typeof body === 'string' ? body : JSON.stringify(body);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
const expected = 'v1=' + mac;
const a = Buffer.from(expected);
const b = Buffer.from(String(signature));
const matches = a.length === b.length && crypto.timingSafeEqual(a, b);
if (!matches) { throw new Error('Signature verification failed'); }
const nowSec = Math.floor(Date.now() / 1000);
if (Math.abs(nowSec - Number(ts)) > 300) { throw new Error('Signature timestamp outside tolerance'); }
return [{ json: { verified: true, eventId, timestamp: ts, body } }];

const item = $input.first().json;
const payload = (item.body && item.body.payload) ? item.body.payload : (item.body || {});

const clientId = String(payload.clientId || payload.client_id || 'unknown').trim();
const clientName = String(payload.clientName || payload.name || 'Account Client').trim();
const clientEmail = String(payload.email || payload.clientEmail || '').trim().toLowerCase();
const daysSinceLastLogin = Number(payload.daysSinceLastLogin || payload.inactivityDays || 0);
const unpaidInvoiceCount = Number(payload.unpaidInvoiceCount || payload.unpaidCount || 0);
const ticketSentimentScore = Number(payload.ticketSentimentScore || payload.sentimentScore || 7);
const contractDaysRemaining = Number(payload.contractDaysRemaining || 180);
const healthScoreDropPct = Number(payload.healthScoreDropPct || 0);

let riskScore = 0;
const riskFactors = [];

if (daysSinceLastLogin >= 30) {
  riskScore += 35;
  riskFactors.push('CRITICAL_PORTAL_INACTIVITY_30D');
} else if (daysSinceLastLogin >= 14) {
  riskScore += 20;
  riskFactors.push('ELEVATED_PORTAL_INACTIVITY_14D');
}

if (unpaidInvoiceCount >= 2) {
  riskScore += 30;
  riskFactors.push('MULTIPLE_UNPAID_INVOICES');
} else if (unpaidInvoiceCount === 1) {
  riskScore += 15;
  riskFactors.push('SINGLE_OVERDUE_INVOICE');
}

if (ticketSentimentScore <= 4) {
  riskScore += 25;
  riskFactors.push('NEGATIVE_SUPPORT_SENTIMENT');
} else if (ticketSentimentScore <= 6) {
  riskScore += 10;
  riskFactors.push('NEUTRAL_LOW_SUPPORT_SENTIMENT');
}

if (contractDaysRemaining <= 30) {
  riskScore += 15;
  riskFactors.push('UPCOMING_CONTRACT_EXPIRATION');
}

if (healthScoreDropPct >= 25) {
  riskScore += 20;
  riskFactors.push('SHARP_HEALTH_SCORE_DROP');
}

riskScore = Math.min(100, riskScore);

let riskTier = 'LOW';
if (riskScore >= 70) {
  riskTier = 'CRITICAL';
} else if (riskScore >= 45) {
  riskTier = 'ELEVATED';
} else if (riskScore >= 20) {
  riskTier = 'MODERATE';
}

const isHighRisk = riskScore >= 45;

return [{
  json: {
    eventId: item.eventId,
    verified: item.verified,
    clientId,
    clientName,
    clientEmail,
    riskScore,
    riskTier,
    riskFactors,
    isHighRisk,
    evaluatedAt: new Date().toISOString()
  }
}];

const item = $input.first().json;
const alertCard = {
  title: `🚨 [RETENTION ALERT] ${item.riskTier} Churn Risk: ${item.clientName}`,
  clientId: item.clientId,
  riskScore: item.riskScore,
  riskTier: item.riskTier,
  riskFactors: item.riskFactors,
  recommendedPlaybook: item.riskTier === 'CRITICAL'
    ? 'Executive emergency sponsor call, milestone review, commercial audit'
    : 'Account manager sync, customer success health check, backlog review',
  escalatedTo: 'Vikash Saravanan (Founder & Lead System Engineer)',
  dispatchedChannels: ['Ops Sentinel Feed', 'VIP Retention Queue']
};

return [{
  json: {
    eventId: item.eventId,
    status: 'churn_retention_alert_triggered',
    detail: {
      clientId: item.clientId,
      clientName: item.clientName,
      riskTier: item.riskTier,
      riskScore: item.riskScore,
      alertCard,
      triggeredAt: new Date().toISOString()
    }
  }
}];

const item = $input.first().json;
return [{
  json: {
    eventId: item.eventId,
    status: 'account_health_stable_logged',
    detail: {
      clientId: item.clientId,
      clientName: item.clientName,
      riskTier: item.riskTier,
      riskScore: item.riskScore,
      riskFactors: item.riskFactors,
      nextPulseScheduled: new Date(Date.now() + 7 * 86400 * 1000).toISOString()
    }
  }
